import os
import re
from collections import defaultdict

ROOT = "/bench/repo"
INTERNAL = os.path.join(ROOT, "internal")

# Map package import path -> directory
pkg_dirs = {}
for dirpath, dirnames, filenames in os.walk(INTERNAL):
    if any(f.endswith('.go') and not f.endswith('_test.go') for f in filenames):
        rel = os.path.relpath(dirpath, ROOT)
        import_path = rel.replace(os.sep, '/')
        pkg_dirs[import_path] = dirpath

# Parse symbols: func Name or func (recv) Name
func_re = re.compile(r'^func (?:\([^)]+\)\s+)?(\w+)\s*\(')
recv_re = re.compile(r'^func \(([^)]+)\)\s+(\w+)\s*\(')

symbols = []  # (symbol_key, filepath, name, is_method, recv_type)

for import_path, dirpath in sorted(pkg_dirs.items()):
    pkg_name = None
    for fn in os.listdir(dirpath):
        if fn.endswith('.go') and not fn.endswith('_test.go'):
            with open(os.path.join(dirpath, fn)) as f:
                for line in f:
                    m = re.match(r'^package (\w+)', line)
                    if m:
                        pkg_name = m.group(1)
                        break
            if pkg_name:
                break
    if not pkg_name:
        continue
    for fn in os.listdir(dirpath):
        if not fn.endswith('.go') or fn.endswith('_test.go'):
            continue
        fpath = os.path.join(dirpath, fn)
        rel_path = os.path.relpath(fpath, ROOT)
        with open(fpath) as f:
            for i, line in enumerate(f, 1):
                rm = recv_re.match(line)
                if rm:
                    recv = rm.group(1).strip()
                    # simplify receiver type
                    recv_type = recv.split('*')[-1].split('.')[-1].strip()
                    name = rm.group(2)
                    if name[0].islower():  # unexported only? count all
                        key = f"{import_path}.{recv_type}.{name}"
                    else:
                        key = f"{import_path}.{recv_type}.{name}"
                    symbols.append((key, rel_path, name, True, recv_type, pkg_name, import_path))
                else:
                    fm = func_re.match(line)
                    if fm and not line.strip().startswith('func ('):
                        name = fm.group(1)
                        key = f"{import_path}.{name}"
                        symbols.append((key, rel_path, name, False, None, pkg_name, import_path))

# Read all non-test, non-proto go files for call counting
go_files = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    if '/web/' in dirpath or '/proto/gen/' in dirpath or '/.git/' in dirpath:
        continue
    for fn in filenames:
        if fn.endswith('.go') and not fn.endswith('_test.go'):
            go_files.append(os.path.join(dirpath, fn))

# Build alias map per file: import alias -> package path
import_re = re.compile(r'^\s*(\w+)\s+"github.com/usememos/memos/([^"]+)"')
import_dot_re = re.compile(r'^\s*\.\s+"github.com/usememos/memos/([^"]+)"')
import_paren_re = re.compile(r'^\s*(\w+)\s+"github.com/usememos/memos/([^"]+)"')

fan_in = defaultdict(set)  # symbol_key -> set of caller files

for gf in go_files:
    rel_gf = os.path.relpath(gf, ROOT)
    try:
        content = open(gf).read()
    except:
        continue
    lines = content.splitlines()

    aliases = {}  # alias -> import_path
    dot_imports = set()
    in_import = False
    for line in lines:
        if line.startswith('import ('):
            in_import = True
            continue
        if in_import:
            if line.strip() == ')':
                in_import = False
                continue
            dm = import_dot_re.match(line)
            if dm:
                dot_imports.add(dm.group(1))
                continue
            im = import_paren_re.match(line)
            if im:
                aliases[im.group(1)] = im.group(2)
        elif line.startswith('import '):
            im = import_paren_re.match(line)
            if im:
                aliases[im.group(1)] = im.group(2)

    # group symbols by package
    by_pkg = defaultdict(list)
    for sym in symbols:
        by_pkg[sym[6]].append(sym)

    for pkg_path, syms in by_pkg.items():
        pkg_name = syms[0][5]
        # possible qualifiers
        quals = {pkg_name}
        for alias, path in aliases.items():
            if path == pkg_path:
                quals.add(alias)
        if pkg_path in dot_imports:
            quals.add('')

        for sym in syms:
            key, def_path, name, is_method, recv_type, _, _ = sym
            caller_hits = set()

            if is_method:
                # Type.Method or alias.Type.Method - usually just recv.Method within package
                # External: pkg.Method if exported, or imported type methods
                patterns = []
                for q in quals:
                    if q:
                        patterns.append(rf'\b{re.escape(q)}\.{re.escape(name)}\s*\(')
                        if recv_type and name[0].isupper():
                            patterns.append(rf'\b{re.escape(q)}\.{re.escape(recv_type)}\.{re.escape(name)}\s*\(')
                    else:
                        patterns.append(rf'\b{re.escape(name)}\s*\(')
                # same package unqualified method call: recvVar.Method(
                patterns.append(rf'\.{re.escape(name)}\s*\(')
            else:
                patterns = []
                for q in quals:
                    if q:
                        patterns.append(rf'\b{re.escape(q)}\.{re.escape(name)}\s*\(')
                    else:
                        patterns.append(rf'\b{re.escape(name)}\s*\(')
                if pkg_path.startswith('internal/'):
                    # within same package unqualified
                    if os.path.dirname(gf) == pkg_dirs.get(pkg_path):
                        patterns.append(rf'\b{re.escape(name)}\s*\(')

            for pat in patterns:
                for m in re.finditer(pat, content):
                    # exclude definition line in same file
                    pos = content[:m.start()].count('\n') + 1
                    if rel_gf == def_path:
                        # crude: skip if line contains 'func '
                        line_at = lines[pos-1] if pos <= len(lines) else ''
                        if 'func ' in line_at and name in line_at:
                            continue
                    caller_hits.add((rel_gf, pos))

            if caller_hits:
                fan_in[key].update(caller_hits)

# Sort by fan-in count
results = [(k, len(v), v) for k, v in fan_in.items()]
results.sort(key=lambda x: -x[1])

print("TOP 25 by fan-in (call sites):")
for key, count, sites in results[:25]:
    def_sym = next(s for s in symbols if s[0] == key)
    print(f"{count:4d}  {key}  ({def_sym[1]})")

