use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = "/bench/repo";
my $INTERNAL = "$ROOT/internal";

# collect internal packages
my %pkg_dirs;
find(sub {
    return unless -f && /\.go$/ && !/_test\.go$/;
    my $dir = $File::Find::dir;
    (my $rel = $dir) =~ s/^\Q$ROOT\E\/?//;
    $pkg_dirs{$rel} = $dir if $rel =~ /^internal\//;
}, $INTERNAL);

# parse symbols
my @symbols;
for my $import_path (sort keys %pkg_dirs) {
    my $dir = $pkg_dirs{$import_path};
    opendir(my $dh, $dir) or next;
    my $pkg_name;
    for my $fn (readdir $dh) {
        next unless $fn =~ /\.go$/ && $fn !~ /_test\.go$/;
        open my $fh, "<", "$dir/$fn" or next;
        while (<$fh>) {
            if (/^package\s+(\w+)/) { $pkg_name = $1; last; }
        }
        close $fh;
        last if $pkg_name;
    }
    next unless $pkg_name;
    for my $fn (readdir $dh) {
        next unless $fn =~ /\.go$/ && $fn !~ /_test\.go$/;
        my $fpath = "$dir/$fn";
        my $rel_path = "$import_path/$fn";
        open my $fh, "<", $fpath or next;
        while (<$fh>) {
            if (/^func\s+\(([^)]+)\)\s+(\w+)\s*\(/) {
                my ($recv, $name) = ($1, $2);
                $recv =~ s/^\*?(\w+\.)?(\w+)$/$2/ if $recv =~ /\*/;
                my $recv_type = $recv;
                $recv_type =~ s/^\*//; $recv_type =~ s/^[\w.]+\.//;
                push @symbols, {
                    key => "$import_path.$recv_type.$name",
                    path => $rel_path,
                    name => $name,
                    method => 1,
                    pkg => $pkg_name,
                    import_path => $import_path,
                };
            } elsif (/^func\s+(\w+)\s*\(/ && !/^func\s+\(/) {
                my $name = $1;
                push @symbols, {
                    key => "$import_path.$name",
                    path => $rel_path,
                    name => $name,
                    method => 0,
                    pkg => $pkg_name,
                    import_path => $import_path,
                };
            }
        }
        close $fh;
    }
    closedir $dh;
}

# collect go files
my @go_files;
find(sub {
    return unless -f && /\.go$/ && !/_test\.go$/;
    my $p = $File::Find::name;
    return if $p =~ m{/web/} || $p =~ m{/proto/gen/} || $p =~ m{/.git/};
    push @go_files, $p;
}, $ROOT);

my %fan_in; # key -> hash of caller site

for my $gf (@go_files) {
    my $rel_gf = $gf; $rel_gf =~ s/^\Q$ROOT\E\/?//;
    open my $fh, "<", $gf or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    my @lines = split /\n/, $content;

    my %aliases;
    my @dot_imports;
    my $in_import = 0;
    for my $line (@lines) {
        if ($line =~ /^import\s+\(/) { $in_import = 1; next; }
        if ($in_import) {
            if ($line =~ /^\)/) { $in_import = 0; next; }
            if ($line =~ /^\s*\.\s+"github\.com\/usememos\/memos\/([^"]+)"/) {
                push @dot_imports, $1;
            } elsif ($line =~ /^\s*(\w+)\s+"github\.com\/usememos\/memos\/([^"]+)"/) {
                $aliases{$1} = $2;
            }
            next;
        }
        if ($line =~ /^import\s+(\w+)\s+"github\.com\/usememos\/memos\/([^"]+)"/) {
            $aliases{$1} = $2;
        }
    }

    my %by_pkg;
    $by_pkg{$_->{import_path}} = [] for @symbols;
    push @{$by_pkg{$_->{import_path}}}, $_ for @symbols;

    for my $pkg_path (keys %by_pkg) {
        my $syms = $by_pkg{$pkg_path};
        next unless @$syms;
        my $pkg_name = $syms->[0]{pkg};
        my %quals = ($pkg_name => 1);
        for my $alias (keys %aliases) {
            $quals{$alias} = 1 if $aliases{$alias} eq $pkg_path;
        }
        my $is_dot = grep { $_ eq $pkg_path } @dot_imports;

        for my $sym (@$syms) {
            my @patterns;
            my $name = $sym->{name};
            if ($sym->{method}) {
                for my $q (keys %quals) {
                    push @patterns, qr/\b\Q$q\E\.\Q$name\E\s*\(/ if $q;
                }
                push @patterns, qr/\.\Q$name\E\s*\(/;
            } else {
                for my $q (keys %quals) {
                    push @patterns, qr/\b\Q$q\E\.\Q$name\E\s*\(/ if $q;
                }
                if ($pkg_dirs{$pkg_path} && dirname($gf) eq $pkg_dirs{$pkg_path}) {
                    push @patterns, qr/\b\Q$name\E\s*\(/;
                }
                if ($is_dot) {
                    push @patterns, qr/\b\Q$name\E\s*\(/;
                }
            }

            for my $pat (@patterns) {
                while ($content =~ /$pat/g) {
                    my $pos = 1 + (substr($content, 0, pos($content) - length($&)) =~ tr/\n//);
                    if ($rel_gf eq $sym->{path}) {
                        my $line = $lines[$pos-1] // "";
                        next if $line =~ /func\s/ && index($line, $name) >= 0;
                    }
                    $fan_in{$sym->{key}}{"$rel_gf:$pos"} = 1;
                }
            }
        }
    }
}

my @sorted = sort { scalar(keys %{$fan_in{$b}}) <=> scalar(keys %{$fan_in{$a}}) } keys %fan_in;
print "TOP 30:\n";
for my $i (0..29) {
    last unless $sorted[$i];
    my $k = $sorted[$i];
    my $n = scalar keys %{$fan_in{$k}};
    my ($path) = grep { $_->{key} eq $k } @symbols;
    print "$n\t$k\t($path->{path})\n";
}
'

