BEGIN {
  root="/bench/repo"
}
function read_internal_symbols(   cmd, f, pkg, line, name, recv, rel, key) {
  cmd="find " root "/internal -name \"*.go\" ! -name \"*_test.go\" -print"
  while ((cmd | getline f) > 0) {
    rel=f; sub("^" root "/","",rel)
    pkg=""
    while ((getline line < f) > 0) {
      if (match(line, /^package ([A-Za-z_][A-Za-z0-9_]*)/, a)) { pkg=a[1]; break }
    }
    close(f)
    if (pkg=="") continue
    pkg_of_file[f]=pkg
    import_path=rel
    sub(/\/[^\/]+$/, "", import_path)
    file_import[f]=import_path
    while ((getline line < f) > 0) {
      if (match(line, /^func \(([^)]+)\) ([A-Za-z_][A-Za-z0-9_]*)\(/, a)) {
        recv=a[1]; name=a[2]
        gsub(/^[[:space:]]*\*?[A-Za-z_][A-Za-z0-9_]*\./, "", recv)
        gsub(/^\*/, "", recv)
        key=import_path "." recv "." name
        def_file[key]=rel
        def_name[key]=name
        is_method[key]=1
        pkg_key[key]=pkg
      } else if (match(line, /^func ([A-Za-z_][A-Za-z0-9_]*)\(/, a)) {
        name=a[1]
        key=import_path "." name
        def_file[key]=rel
        def_name[key]=name
        is_method[key]=0
        pkg_key[key]=pkg
      }
    }
    close(f)
  }
  close(cmd)
}
function parse_imports(content,   i,n,lines,line,alias,path) {
  delete aliases; delete dot_paths; n=split(content,lines,"\n")
  in_import=0
  for(i=1;i<=n;i++) {
    line=lines[i]
    if (line ~ /^import \(/) { in_import=1; continue }
    if (in_import) {
      if (line ~ /^\)/) { in_import=0; continue }
      if (match(line, /^\s*\.\s+"github\.com\/usememos\/memos\/([^"]+)"/, a)) dot_paths[a[1]]=1
      else if (match(line, /^\s*([A-Za-z_][A-Za-z0-9_]*)\s+"github\.com\/usememos\/memos\/([^"]+)"/, a)) aliases[a[1]]=a[2]
      continue
    }
    if (match(line, /^import ([A-Za-z_][A-Za-z0-9_]*) "github\.com\/usememos\/memos\/([^"]+)"/, a)) aliases[a[1]]=a[2]
  }
}
function count_calls(content, caller,   key,name,pkg,import_path,q,pat,n,hits) {
  for (key in def_name) {
    name=def_name[key]
    import_path=key
    sub(/\.[^.]*$/, "", import_path)
    if (is_method[key]) {
      sub(/\.[^.]*$/, "", import_path) # wrong for methods - fix below
    }
    # recompute import_path from key
    split(key, parts, ".")
    import_path=parts[1]
    for (i=2; i<=length(parts)- (is_method[key]?2:1); i++) import_path=import_path "." parts[i]
    pkg=pkg_key[key]
    hits=0
    # qualified pkg.name(
    pat="(^|[^A-Za-z0-9_])" pkg "\\." name "[[:space:]]*\\("
    hits += count_pat(content, pat, caller, def_file[key])
    for (q in aliases) if (aliases[q]==import_path) {
      pat="(^|[^A-Za-z0-9_])" q "\\." name "[[:space:]]*\\("
      hits += count_pat(content, pat, caller, def_file[key])
    }
    if (dot_paths[import_path]) {
      pat="(^|[^A-Za-z0-9_])" name "[[:space:]]*\\("
      hits += count_pat(content, pat, caller, def_file[key])
    }
    # same package unqualified
    if (caller_pkg[caller]==pkg && caller_dir[caller]==import_path) {
      pat="(^|[^A-Za-z0-9_])" name "[[:space:]]*\\("
      hits += count_pat(content, pat, caller, def_file[key])
    }
    # method receiver .name(
    if (is_method[key]) {
      pat="\\." name "[[:space:]]*\\("
      hits += count_pat(content, pat, caller, def_file[key])
    }
    if (hits>0) fan_in[key]+=hits
  }
}
function count_pat(content, pat, caller, defpath,   pos, line, n,lines,cnt) {
  cnt=0; n=split(content,lines,"\n")
  for (line=1;line<=n;line++) {
    if (lines[line] ~ pat) {
      if (caller==defpath && lines[line] ~ /func[[:space:]]/) continue
      cnt++
    }
  }
  return cnt
}
